from tests.test_orders import order


def test_customers_without_orders_lists_every_customer_when_nobody_has_ordered(shop):
    response = shop.insights.handle_customers_without_orders()
    assert response.status == 200
    assert [c["customer_id"] for c in response.body["customers"]] == ["c1", "c2"]


def test_customers_without_orders_includes_name_and_email(shop):
    customers = shop.insights.handle_customers_without_orders().body["customers"]
    assert customers[0] == {"customer_id": "c1", "name": "Ada", "email": "ada@example.com"}


def test_customers_without_orders_leaves_out_customers_with_a_live_order(shop):
    order(shop, "c1", ("PEN", 1))
    ids = [c["customer_id"] for c in shop.insights.handle_customers_without_orders().body["customers"]]
    assert ids == ["c2"]


def test_customers_without_orders_includes_customers_whose_orders_are_all_cancelled(shop):
    oid = order(shop, "c1", ("PEN", 1)).body["order_id"]
    shop.orders.handle_cancel(oid)
    ids = [c["customer_id"] for c in shop.insights.handle_customers_without_orders().body["customers"]]
    assert ids == ["c1", "c2"]


def test_customers_without_orders_is_empty_when_everyone_has_ordered(shop):
    order(shop, "c1", ("PEN", 1))
    order(shop, "c2", ("PEN", 1))
    assert shop.insights.handle_customers_without_orders().body == {"customers": []}


def test_customers_without_orders_keeps_registration_order(shop):
    shop.customers.handle_register({"customer_id": "c0", "name": "Alan", "email": "alan@example.com"})
    ids = [c["customer_id"] for c in shop.insights.handle_customers_without_orders().body["customers"]]
    assert ids == ["c1", "c2", "c0"]

